1	/* =====================================================================
2	 * measure_envelope_arm64_v4.c — TASK-20260810-2a0a37 (GOAL-AES-002/BATCH-2b0fd1)
3	 *
4	 * REPAIR v4 of the arm64 hardware-AES benchmark, by new immutable path.
5	 * Full lineage preserved: v1 composed AESMC(AESE(x, rk)) — WRONG, because
6	 * ARM AESE XORs the round key BEFORE AESMC applies MixColumns, so that
7	 * composition computes MC(SR(SB(x))) ^ MC(rk), not ^ rk (0/8 openssl
8	 * agreement, run2-aesni.json era). v2 pre-transformed round keys but then
9	 * mis-derived the ShiftRows convention. v3 probed AESE's permutation
10	 * (sigma = 0 5 10 15 4 9 14 3 8 13 2 7 12 1 6 11) and — reading that as
11	 * NON-standard — applied a "correction" permutation rho. THE DIAGNOSIS OF
12	 * THIS SESSION: that probed sigma IS EXACTLY standard FIPS-197 ShiftRows
13	 * under the out[i] = in[tau[i]] convention (tau[i] = 4*((i div 4 + i mod 4)
14	 * mod 4) + i mod 4), which evaluates to the very sequence probed; the prior
15	 * session's "tau" was the transposed (column-shift) map and its rho
16	 * therefore scrambled a correct instruction. v4 composes the round
17	 * explicitly and safely with NO permutation correction and NO key
18	 * pre-transform:
19	 *     x ^= rk[0]
20	 *     rounds 1..9:  x = AESMC( AESE(x, ZERO) ) ^ rk[r]   (zero-key AESE,
21	 *                   MixColumns, then plain vector XOR of the round key —
22	 *                   algebraically identical to MC(SR(SB(x))) ^ rk[r])
23	 *     round 10:     x = AESE(x, rk[10])                  (SR(SB(x)) ^ rk[10])
24	 * Everything is adjudicated by execution: the selftest reproduces the
25	 * FIPS-197 AES-128 known-answer vector, and the driver cross-checks the
26	 * 'vec' mode against the openssl CLI before any throughput number is
27	 * admitted. NOTHING is trusted because it was recalled.
28	 *
29	 * Benchmark ONLY; NO cryptanalysis; no key recovery; no distinguisher;
30	 * nothing asserted about AES security at any round count; infrastructure
31	 * failures are infrastructure signal, never negative mathematical evidence
32	 * (AGENTS.md rule 5); this artifact is expressly NOT a completion
33	 * (GOAL-AES-002 non_completion_criteria (vi)).
34	 *
35	 * ------------------- COMMENT-BLOCK INFERENCE STANZA -------------------
36	 * authored_by_task: TASK-20260810-2a0a37
37	 * authored_by_role: executor
38	 * handoff_inference_policy: executor-implementation
39	 * handoff_reasoning_effort: null (policy default)
40	 * fallback_used: false
41	 * degraded_allowed: false
42	 * degraded_requirements: []
43	 * resolved_model_id: null (not surfaced by this runtime; unverified
44	 *   configuration until a doctor --probe confirms a backend serves it)
45	 * resolved_runtime: claude-code session (api_direct-equivalent tool set)
46	 * bedrock: NOT selected, configured, probed or contacted, and never may
47	 *   be (AGENTS.md rule 16; task constraint SC-11)
48	 * claim_tier_of_this_artifact: infrastructure measurement only; no
49	 *   margin, no cryptanalytic claim, nothing about AES at any round
50	 *   count; R5 of RQ-AES-002 binds any later record quoting these numbers.
51	 * -----------------------------------------------------------------------
52	 * ===================================================================== */
53	#include <stdio.h>
54	#include <stdlib.h>
55	#include <string.h>
56	#include <stdint.h>
57	#include <time.h>
58	#include <arm_neon.h>
59	
60	static unsigned char SBOX[256];
61	static unsigned char RCON[11];
62	
63	static uint8_t gmul(uint8_t a, uint8_t b) {
64	    uint8_t p = 0;
65	    while (b) {
66	        if (b & 1) p ^= a;
67	        uint8_t hi = a & 0x80;
68	        a = (uint8_t)(a << 1);
69	        if (hi) a ^= 0x1b;
70	        b >>= 1;
71	    }
72	    return p;
73	}
74	
75	/* Tables are COMPUTED from the AES definition: GF(2^8) inversion under
76	 * x^8+x^4+x^3+x+1, then the affine map; Rcon by GF doubling. */
77	static void init_tables(void) {
78	    for (int x = 0; x < 256; x++) {
79	        uint8_t inv = 0;
80	        if (x) { for (int y = 1; y < 256; y++) if (gmul((uint8_t)x,(uint8_t)y)==1) { inv=(uint8_t)y; break; } }
81	        uint8_t a = inv;
82	        for (int r = 1; r <= 4; r++) { a = (uint8_t)((a << 1) | (a >> 7)); inv ^= a; }
83	        SBOX[x] = (uint8_t)(inv ^ 0x63);
84	    }
85	    uint8_t r = 1;
86	    RCON[0] = 0x00;
87	    for (int i = 1; i <= 10; i++) { RCON[i] = r; r = gmul(r, 2); }
88	}
89	
90	/* Standard AES-128 key schedule, word-based (w[44] of 4 bytes each),
91	 * written from the FIPS-197 definition; adjudicated by the selftest. */
92	static void expand_key(const unsigned char key[16], unsigned char rk[11][16]) {
93	    unsigned char w[44][4];
94	    for (int i = 0; i < 4; i++) { memcpy(w[i], key + 4*i, 4); }
95	    for (int i = 4; i < 44; i++) {
96	        unsigned char t[4];
97	        memcpy(t, w[i-1], 4);
98	        if (i % 4 == 0) {
99	            unsigned char u[4] = { (unsigned char)SBOX[t[1]], (unsigned char)SBOX[t[2]],
100	                                  (unsigned char)SBOX[t[3]], (unsigned char)SBOX[t[0]] };
101	            u[0] ^= RCON[i/4];
102	            memcpy(t, u, 4);
103	        }
104	        for (int k = 0; k < 4; k++) w[i][k] = (unsigned char)(w[i-4][k] ^ t[k]);
105	    }
106	    for (int r = 0; r < 11; r++) memcpy(rk[r], w[4*r], 16);
107	}
108	
109	static inline uint8x16_t enc_block(uint8x16_t pt, const unsigned char rk[11][16]) {
110	    uint8x16_t x = veorq_u8(pt, vld1q_u8(rk[0]));
111	    uint8x16_t zero = vdupq_n_u8(0);
112	    for (int r = 1; r <= 9; r++) {
113	        x = vaeseq_u8(x, zero);        /* SR(SB(x)) ^ 0 */
114	        x = vaesmcq_u8(x);             /* MC(SR(SB(x))) */
115	        x = veorq_u8(x, vld1q_u8(rk[r])); /* ^ rk[r] : the AES round */
116	    }
117	    x = vaeseq_u8(x, vld1q_u8(rk[10])); /* final round: SR(SB(x)) ^ rk[10] */
118	    return x;
119	}
120	
121	static double now_s(void) {
122	    struct timespec ts;
123	    clock_gettime(CLOCK_MONOTONIC, &ts);
124	    return (double)ts.tv_sec + 1e-9 * (double)ts.tv_nsec;
125	}
126	
127	static void print_hex(const unsigned char *p, int n) {
128	    for (int i = 0; i < n; i++) printf("%02x", p[i]);
129	}
130	
131	static void selftest(void) {
132	    const unsigned char key[16] = {0x00,0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08,0x09,0x0a,0x0b,0x0c,0x0d,0x0e,0x0f};
133	    const unsigned char pt[16]  = {0x00,0x11,0x22,0x33,0x44,0x55,0x66,0x77,0x88,0x99,0xaa,0xbb,0xcc,0xdd,0xee,0xff};
134	    unsigned char rk[11][16];
135	    unsigned char ct[16];
136	    expand_key(key, rk);
137	    uint8x16_t c = enc_block(vld1q_u8(pt), (const unsigned char (*)[16])rk);
138	    vst1q_u8(ct, c);
139	    printf("SELFTEST ct=");
140	    print_hex(ct, 16);
141	    printf(" fips197_expected=69c4e0d86a7b0430d8cdb78070b4c55a match=%s\n",
142	           memcmp(ct, "\x69\xc4\xe0\xd8\x6a\x7b\x04\x30\xd8\xcd\xb7\x80\x70\xb4\xc5\x5a", 16) == 0 ? "yes" : "NO");
143	}
144	
145	/* vec mode: lines "keyhex pthex" on stdin -> "ct=..." lines on stdout. */
146	static void vec_mode(void) {
147	    char line[256];
148	    unsigned char key[16], pt[16], rk[11][16], ct[16];
149	    while (fgets(line, sizeof line, stdin)) {
150	        if (line[0] == '#' || line[0] == '\n') continue;
151	        char kh[64], ph[64];
152	        if (sscanf(line, "%63s %63s", kh, ph) != 2) continue;
153	        for (int i = 0; i < 16; i++) {
154	            unsigned int k, p;
155	            sscanf(kh + 2*i, "%2x", &k);
156	            sscanf(ph + 2*i, "%2x", &p);
157	            key[i] = (unsigned char)k; pt[i] = (unsigned char)p;
158	        }
159	        expand_key(key, rk);
160	        uint8x16_t c = enc_block(vld1q_u8(pt), (const unsigned char (*)[16])rk);
161	        vst1q_u8(ct, c);
162	        printf("ct=");
163	        print_hex(ct, 16);
164	        printf("\n");
165	    }
166	}
167	
168	/* Deterministic pseudo-key/plaintext stream: xorshift-style, no libc rand. */
169	static uint64_t rng_state = 0x2A0A3700B4E5C1D3ull;
170	static inline uint64_t rng(void) {
171	    rng_state ^= rng_state << 13; rng_state ^= rng_state >> 7; rng_state ^= rng_state << 17;
172	    return rng_state;
173	}
174	
175	int main(int argc, char **argv) {
176	    init_tables();
177	    if (argc < 2) { fprintf(stderr, "usage: %s selftest | vec | bench <fresh|dep|ind> <N> <reps>\n", argv[0]); return 2; }
178	    if (!strcmp(argv[1], "selftest")) { selftest(); return 0; }
179	    if (!strcmp(argv[1], "vec"))      { vec_mode();  return 0; }
180	    if (!strcmp(argv[1], "bench") && argc == 5) {
181	        const char *mode = argv[2];
182	        long N = atol(argv[3]);
183	        int reps = atoi(argv[4]);
184	        unsigned char rk[11][16];
185	        uint64_t acc = 0;
186	        for (int rep = 1; rep <= reps; rep++) {
187	            double t0 = now_s();
188	            if (!strcmp(mode, "fresh")) {
189	                /* CM-1 AEU-128 shape: schedule CHARGED per evaluation. */
190	                unsigned char key[16]; unsigned char pt[16]; unsigned char ct[16];
191	                for (int i = 0; i < 16; i++) { key[i] = 0; pt[i] = 0; }
192	                for (long i = 0; i < N; i++) {
193	                    uint64_t r = rng();
194	                    for (int b = 0; b < 16; b++) key[b] = (unsigned char)(r >> (4*b));
195	                    r = rng();
196	                    for (int b = 0; b < 16; b++) pt[b] = (unsigned char)(r >> (4*b));
197	                    expand_key(key, rk);
198	                    vst1q_u8(ct, enc_block(vld1q_u8(pt), (const unsigned char (*)[16])rk));
199	                    acc ^= ct[0]; acc ^= (uint64_t)ct[15] << 56;
200	                }
201	            } else if (!strcmp(mode, "dep")) {
202	                /* One key; dependent chain (latency-bound). */
203	                unsigned char key[16], ct[16];
204	                for (int i = 0; i < 16; i++) key[i] = (unsigned char)(i ^ 0x5A);
205	                expand_key(key, rk);
206	                uint8x16_t x = vdupq_n_u8(0);
207	                for (long i = 0; i < N; i++) {
208	                    x = enc_block(x, (const unsigned char (*)[16])rk);
209	                    acc ^= vgetq_lane_u64(vreinterpretq_u64_u8(x), 0);
210	                }
211	                /* touch acc so the chain is not optimised away */
212	                if (acc == 0xDEADBEEFull) printf("x");
213	            } else if (!strcmp(mode, "ind")) {
214	                /* One key; independent blocks (throughput-bound, pipelined).
215	                 * Implemented as 4 interleaved dependent chains so the
216	                 * compiler cannot serialise them: still independent work. */
217	                unsigned char key[16];
218	                for (int i = 0; i < 16; i++) key[i] = (unsigned char)(i ^ 0xA5);
219	                expand_key(key, rk);
220	                uint8x16_t x0=vdupq_n_u8(0), x1=vdupq_n_u8(1), x2=vdupq_n_u8(2), x3=vdupq_n_u8(3);
221	                for (long i = 0; i < N; i += 4) {
222	                    x0 = enc_block(x0, (const unsigned char (*)[16])rk);
223	                    x1 = enc_block(x1, (const unsigned char (*)[16])rk);
224	                    x2 = enc_block(x2, (const unsigned char (*)[16])rk);
225	                    x3 = enc_block(x3, (const unsigned char (*)[16])rk);
226	                }
227	                uint8x16_t all = veorq_u8(veorq_u8(x0,x1), veorq_u8(x2,x3));
228	                acc ^= vgetq_lane_u64(vreinterpretq_u64_u8(all), 0);
229	                acc ^= vgetq_lane_u64(vreinterpretq_u64_u8(all), 1);
230	            } else {
231	                fprintf(stderr, "unknown bench mode\n"); return 2;
232	            }
233	            double dt = now_s() - t0;
234	            printf("RESULT mode=%s N=%ld rep=%d elapsed_s=%.6f rate=%.6e acc=%llx\n",
235	                   mode, N, rep, dt, (double)N / dt, (unsigned long long)(acc & 0xFFFFFFFFFFFFFFFFull));
236	        }
237	        return 0;
238	    }
239	    fprintf(stderr, "bad arguments\n"); return 2;
240	}

